#!/usr/bin/env python3
"""Build and execute the audit companion; publication assets remain script-owned."""
from pathlib import Path
import html, json, io, contextlib, os
import nbformat as nbf


HERE=Path(__file__).resolve().parents[1]
def main():
    n=nbf.v4.new_notebook()
    md=nbf.v4.new_markdown_cell;code=nbf.v4.new_code_cell
    n.cells=[
      md('# HeteroSpec MLSys 2027 figure audit\n\n## tl;dr\nFour main figures and one appendix inventory preserve the frozen scientific classes. Eleven verification microbenchmark cells were replayed; both M4 prompt-bootstrap CIs and all 180 358H paired observations reconcile. The 358H CPU/NPU means are 13.25/27.54 post-prefill seconds per request. The committed manuscript figures were directly compared with v0.2 and selected v0.3 assets; see comparison/OLD_NEW_COMPARISON.pdf.\n\nThis notebook is an audit companion. Final PDF/SVG figures are generated by `scripts/plot.py`, never from notebook screenshots.'),
      md('## Context & Methods\n\nSource commit: `1a11361f8526ec361e20dd6878d6e67352fb7bbd`. Authority: `PAPER_FRAMEWORK_HANDOFF.md`, the framework/mechanism notes, and frozen evidence.\n\n### Key Assumptions\n- Correctness means frozen generated-token equality, not functional HumanEval performance.\n- Microbenchmark ranges are across contexts, not CIs or fully matched hardware comparisons.\n- Phase-1 steady-state throughput differs from Phase-3 realized stateful costs.\n- Arithmetic cost means and prompt-GM speedup are distinct estimands.\n- Only repository evidence is used. Full source hashes are in `data/source_lock.json`.'),
      code("from pathlib import Path\nimport json, subprocess, sys\nimport pandas as pd\nfrom IPython.display import display, Image\nHERE = Path.cwd()\nassert (HERE / 'scripts/extract.py').is_file()\npd.set_option('display.max_columns', 8)\npd.set_option('display.width', 110)"),
      md('## Data\n\n### 1. Re-extract and check source fitness\nThe extractor rejects duplicate/missing selected rows and the historical header-only Phase-3 scaffold. It locks every consumed file with SHA256 and the Git blob identifier.'),
      code("r = subprocess.run([sys.executable, 'scripts/extract.py'], check=True, capture_output=True, text=True)\nprint(r.stdout.strip())\nquality = json.loads((HERE/'qa/data_quality.json').read_text())\nprint('Data-quality status:', quality['status'])\nprint('Pinned sources:', len(json.loads((HERE/'data/source_lock.json').read_text())))"),
      md('### 2. Independent numerical and exported-vector validation\nThis pass does not import extraction or plotting helpers. It replays raw timing medians, campaign-specific bootstrap protocols and paired timing decompositions.'),
      code("r = subprocess.run([sys.executable, 'scripts/validate.py', '--require-outputs'], check=True, capture_output=True, text=True)\nprint(r.stdout.strip())"),
      md('## Results\n\n### Verification paths\nAll eleven cells remain inspectable. Fast and serialized B570 measurements are diagnostic; the formal failed-gate result is not replaced.'),
      code("micro=pd.read_csv(HERE/'data/figure2_micro_cells.csv')\ndisplay(micro[['path','context','v2_micro','repetitions','status']].round(6))\ndisplay(Image(filename=str(HERE/'qa/figure2_180dpi.png'),width=810))"),
      md('### M4 workload contrast\nTwo separately frozen studies. Their prompt-level bootstrap CIs do not provide a statistically paired between-workload contrast.'),
      code("display(pd.read_csv(HERE/'data/figure3_workloads.csv')[['workload','speedup','ci_low','ci_high','exact_pairs']].round(6))\ndisplay(Image(filename=str(HERE/'qa/figure3_180dpi.png'),width=390))"),
      md('### 358H isolated and realized boundaries\nFive repetitions per isolated context/device cell. The Phase-1 CSV/JSON are checked against retained TPOT vectors; independently archived raw throughput arrays were unavailable in the repository snapshot. Phase-3 replay and proposal share one OpenVINO call and cannot be split retrospectively.'),
      code("display(pd.read_csv(HERE/'data/figure4_isolated.csv')[['device','context','tokens_s','ci_low','ci_high']].round(5))\ndisplay(pd.read_csv(HERE/'data/figure4_realized.csv')[['device','total_s','draft_s','target_s','residual_s','headline_speedup','aggregate_speedup']].round(6))\ndisplay(Image(filename=str(HERE/'qa/figure4_180dpi.png'),width=810))"),
      md('### Empirical overview and appendix inventory\nBlocked paths have no admissible profitability coordinate. Row order is categorical and does not rank hardware. The overview presents heterogeneous local measurements and realized outcomes without a shared numerical axis.'),
      code("display(Image(filename=str(HERE/'qa/figure5_180dpi.png'),width=810))\ndisplay(Image(filename=str(HERE/'qa/figure1_180dpi.png'),width=810))"),
      md('## Takeaways\n\n- The cheapest physical target-forward path need not satisfy the frozen correctness contract.\n- In this qualified adapter, isolated NPU throughput does not represent realized draft cost.\n- B570 serialization improves observed exactness to 60/90 but remains inadmissible.\n- Publication-candidate status applies to the new standalone assets at checked native widths.\n- Actual OLD-versus-NEW selection is complete: redesign F1, take F2/F4, hybrid F3, appendix-only F5; see `FIGURE_REVIEW.md`.\n\nRead `FIGURE_MANIFEST.md`, `qa/VISUAL_QA.md`, and `data/source_lock.json` for evidence classes, source boundaries and final SHA256 values.')]
    n.metadata={'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'},'language_info':{'name':'python','version':__import__('platform').python_version()}}
    nbf.validate(n)
    # This environment disallows Jupyter TCP and IPC sockets. Execute these plain
    # Python cells in a fresh namespace, in order, with explicit display capture.
    # The saved notebook remains standard nbformat and runnable in Jupyter.
    import IPython.display as ipd
    prior_display=ipd.display; prior_cwd=Path.cwd(); namespace={}; count=0
    outputs=[]
    def capture_display(*objs,**kwargs):
        for obj in objs:
            if hasattr(obj,'_repr_mimebundle_'):
                bundle=obj._repr_mimebundle_()
                if isinstance(bundle,tuple):bundle=bundle[0]
            elif hasattr(obj,'to_html'):bundle={'text/html':obj.to_html(),'text/plain':repr(obj)}
            else:bundle={'text/plain':repr(obj)}
            outputs.append(nbf.v4.new_output('display_data',data=bundle,metadata={}))
    try:
        os.chdir(HERE);ipd.display=capture_display
        for cell in n.cells:
            if cell.cell_type!='code':continue
            count+=1;outputs=[];stream=io.StringIO()
            with contextlib.redirect_stdout(stream):
                exec(compile(cell.source,'figure_audit.ipynb cell '+str(count),'exec'),namespace)
            if stream.getvalue():outputs.insert(0,nbf.v4.new_output('stream',name='stdout',text=stream.getvalue()))
            cell.outputs=outputs;cell.execution_count=count
    finally:
        ipd.display=prior_display;os.chdir(prior_cwd)
    n.metadata['execution_note']='Plain Python cells executed top-to-bottom in a fresh namespace. Jupyter kernel TCP/IPC sockets unavailable in authoring sandbox.'
    nbf.write(n,HERE/'figure_audit.ipynb')
    nbf.validate(nbf.read(HERE/'figure_audit.ipynb',as_version=4))
    # Minimal, self-contained saved-output preview for visual inspection.
    pieces=['<!doctype html><meta charset="utf-8"><title>Figure audit notebook</title><style>body{max-width:1000px;margin:36px auto;font:16px/1.45 system-ui;color:#252a2d}pre{white-space:pre-wrap;background:#f4f5f6;padding:14px;font-size:13px}img{max-width:100%;height:auto}table{border-collapse:collapse;font-size:13px}td,th{padding:5px 9px;border-bottom:1px solid #ddd}.md{white-space:pre-wrap;margin:24px 0}section{margin-bottom:28px}</style>']
    for c in n.cells:
        pieces.append('<section>')
        if c.cell_type=='markdown': pieces.append('<div class="md">'+html.escape(c.source)+'</div>')
        else:
            pieces.append('<pre>'+html.escape(c.source)+'</pre>')
            for o in c.get('outputs',[]):
                if o.output_type=='stream':pieces.append('<pre>'+html.escape(o.text)+'</pre>')
                elif 'data' in o:
                    if 'image/png' in o.data:pieces.append('<img src="data:image/png;base64,'+o.data['image/png']+'">')
                    elif 'text/html' in o.data:pieces.append(o.data['text/html'])
                    elif 'text/plain' in o.data:pieces.append('<pre>'+html.escape(o.data['text/plain'])+'</pre>')
        pieces.append('</section>')
    (HERE/'qa/notebook_preview.html').write_text('\n'.join(pieces))
    print('Notebook validated and executed top-to-bottom; saved outputs and self-contained HTML preview.')

if __name__=='__main__': main()
